.syx{--gold:#EBC66C;--gold2:#F4D275;--goldg:linear-gradient(135deg,#E0B05A 0%,#F4D275 50%,#E4B85E 100%);--bronze:#C5965D;--soft:#E6EFF9;--soft2:#CEDAE8;--navy:#060b16;--navy2:#0a1428;--navy3:#0e1c38;--blue:#3fa4ff;--cream:#F6F1E6;--ink:#06101c;--text:#F3EFE6;--mute:#a9b3c6;--line:rgba(235,198,108,.38);
 --out:cubic-bezier(.23,1,.32,1);
 font-family:"Heebo",system-ui,sans-serif;color:var(--text);direction:rtl;text-align:right;line-height:1.6;
 -webkit-font-smoothing:antialiased;-moz-osx-font-smoothing:grayscale;overflow-x:clip;position:relative;isolation:isolate}
