@keyframes syxSheen{0%{transform:translateX(280%) skewX(-12deg)}60%,100%{transform:translateX(-120%) skewX(-12deg)}}
.syx-hero .spot{position:absolute;z-index:2;width:560px;height:560px;left:0;top:0;margin:-280px 0 0 -280px;border-radius:50%;background:radial-gradient(circle,rgba(255,215,130,.2),transparent 62%);mix-blend-mode:screen;pointer-events:none;transform:translate3d(var(--sx,50vw),var(--sy,40vh),0);will-change:transform;opacity:0;transition:opacity .6s ease}
