}

/* about (cream) */
.syx-about .grid{display:grid;grid-template-columns:1fr 1fr;gap:clamp(28px,5vw,64px);align-items:center}
.syx .linkline{display:inline-flex;align-items:center;gap:8px;min-height:44px;font-weight:700;color:#24292d;border-bottom:2px solid #C5965D;transition:gap .3s var(--out)}
